  return `<div class="expanded-message" ${isLast?'':'data-expanded-message'}>${avatar({avatar:initials,color:t.color})}<div class="message-body-wrap"><div class="message-person"><div><strong>${esc(m.fromName || t.fromName)}</strong><span class="email-address">&lt;${esc(m.email || t.from)}&gt;</span><div class="to-line">to ${esc(t.toName || (t.to || 'me'))} <button data-action="details" title="Show details">${icon('chevron')}</button></div></div><time>${new Date(m.date || t.date).toLocaleString([], {month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}</time><button class="icon-button small" data-action="reply" title="Reply">${icon('reply')}</button><button class="icon-button small" data-action="more-reader" title="More">${icon('moreVertical')}</button></div><div class="message-body">${esc(m.body || t.body).replace(/\n/g,'<br>')}</div>${isLast&&t.attachments.length?`<div class="attachment-block"><div class="attachment-caption">${t.attachments.length} attachment${t.attachments.length>1?'s':''}</div><div class="attachment-list">${t.attachments.map(file=>attachmentCard(file)).join('')}</div></div>`:''}</div></div>`;
}
function renderReader(t) {
  if (!t) { openThreadId = null; return renderInbox(visibleThreads(), false); }
  const messages = t.messages?.length ? t.messages : [{fromName:t.fromName,email:t.from,date:t.date,body:t.body}];
  return `<div class="reader-toolbar"><div class="reader-toolbar-left"><button class="icon-button" data-action="back" title="Back to inbox">${icon('back')}</button><span class="toolbar-divider"></span><button class="icon-button" data-action="archive-one" title="Archive">${icon('archive')}</button><button class="icon-button" data-action="delete-one" title="Delete">${icon('trash')}</button><button class="icon-button" data-action="snooze-one" title="Snooze">${icon('snooze')}</button><span class="toolbar-divider"></span><button class="icon-button" data-action="mark-unread" title="Mark unread">${icon('drafts')}</button><button class="icon-button" data-action="label-menu" title="Labels">${icon('label')}</button><button class="icon-button" data-action="more-reader" title="More">${icon('more')}</button></div><div class="reader-toolbar-right"><span>${esc(titleForView())}</span><button class="icon-button" data-action="previous-message" title="Newer">${icon('back')}</button><button class="icon-button" data-action="next-message" title="Older">${icon('chevronRight')}</button></div></div>
    <div class="reader-scroll"><div class="reader-header"><div class="reader-title-row"><h1>${esc(t.subject || '(no subject)')}</h1><button class="star-button reader-star ${t.starred?'starred':''}" data-star="${t.id}" aria-label="${t.starred?'Unstar':'Star'} message">${icon('star')}</button></div><div class="reader-labels">${t.labels.map(label=>`<span class="message-label ${labelColor(label)}">${esc(label)}</span>`).join('')}<button class="add-reader-label" data-action="label-menu" aria-label="Add label">+</button></div>
    ${messages.length>1 ? messages.slice(0,-1).map((m,i)=>`<button class="collapsed-message" data-expand-message="${i}">${avatar({avatar:(m.fromName||'?').split(' ').map(x=>x[0]).join('').slice(0,2),color:'gray'})}<span><strong>${esc(m.fromName)}</strong><small>${esc(m.body.split('\n')[0].slice(0,90))}…</small></span><time>${fmtDate(m.date)}</time></button>`).join(''):''}
    ${renderMessageCard(t,messages[messages.length-1],true)}
    <div class="reader-actions"><button class="outline-action" data-action="reply">${icon('reply')} Reply</button><button class="outline-action" data-action="forward">${icon('forward')} Forward</button><button class="icon-button reader-more" data-action="more-reader" aria-label="More">${icon('more')}</button></div>
    </div><aside class="reader-aside"><div class="aside-card"><span class="aside-icon">${icon('checkCircle')}</span><strong>Nothing else to do</strong><small>This conversation is up to date.</small></div><div class="aside-tip"><span>✦</span><p>Keep your inbox calm. Archive conversations you’re done with.</p></div></aside></div>`;
}
function attachmentCard(file) { const ext = (file.name.split('.').pop()||'FILE').toUpperCase(); return `<button class="attachment-card" data-attachment="${esc(file.name)}"><span class="file-art ${esc(file.type||'file')}">${ext==='PDF'?'PDF':ext==='XLSX'?'XLS':'FIG'}</span><span><strong>${esc(file.name)}</strong><small>${esc(file.size || 'File')}</small></span><span class="download-icon">${icon('more')}</span></button>`; }
function renderAttachmentPreview(file) { return `<div class="preview-scrim" data-action="close-preview"><section class="attachment-preview" role="dialog" aria-modal="true" aria-label="Attachment details"><div class="preview-header"><strong>Attachment details</strong><button class="icon-button" data-action="close-preview" aria-label="Close">${icon('close')}</button></div><div class="preview-content"><span class="file-art ${esc(file.type||'file')}">${esc((file.name.split('.').pop()||'FILE').slice(0,4).toUpperCase())}</span><h2>${esc(file.name)}</h2><p>${esc(file.size||'File')} · ${esc((file.type||'file').toUpperCase())}</p><div class="preview-note">This message includes this attachment.</div></div></section></div>`; }
function renderCompose() {
  const c = composeState;
  return `<div class="compose-window ${c.maximized?'maximized':''} ${c.minimized?'minimized':''}" role="dialog" aria-label="New message"><div class="compose-topline"><strong>${c.id?'Draft':'New message'}</strong><div><button data-action="minimize-compose" title="Minimize">−</button><button data-action="maximize-compose" title="Full screen">□</button><button data-action="close-compose" title="Save and close">${icon('close')}</button></div></div>${c.minimized?'':`<div class="compose-fields"><div class="compose-field"><label for="compose-to">To</label><input id="compose-to" value="${esc(c.to)}" placeholder="Recipients" autocomplete="off"/><button data-action="show-cc">Cc</button><button data-action="show-bcc">Bcc</button></div>${c.showCc?`<div class="compose-field"><label for="compose-cc">Cc</label><input id="compose-cc" value="${esc(c.cc||'')}" placeholder="Add Cc recipients"/></div>`:''}${c.showBcc?`<div class="compose-field"><label for="compose-bcc">Bcc</label><input id="compose-bcc" value="${esc(c.bcc||'')}" placeholder="Add Bcc recipients"/></div>`:''}<div class="compose-field"><label for="compose-subject">Subject</label><input id="compose-subject" value="${esc(c.subject)}" placeholder="Subject"/></div></div><textarea id="compose-body" placeholder="Write your message…">${esc(c.body)}</textarea>${c.attachments.length?`<div class="compose-attachments">${c.attachments.map((f,i)=>`<span>${icon('attach')} ${esc(f.name)} <button data-remove-attachment="${i}" aria-label="Remove attachment">×</button></span>`).join('')}</div>`:''}<div class="compose-footer"><div class="compose-tools"><button class="send-button" data-action="send">Send <span class="send-menu">⌄</span></button><button class="icon-button" data-action="format" title="Formatting options">A</button><label class="icon-button attach-control" title="Attach files">${icon('attach')}<input type="file" id="file-attach" multiple hidden/></label><button class="icon-button" data-action="insert-link" title="Insert link">↗</button><button class="icon-button" data-action="emoji" title="Insert emoji">☺</button><button class="icon-button compose-more" data-action="compose-more" title="More options">${icon('more')}</button></div><button class="icon-button delete-draft" data-action="discard-compose" title="Discard draft">${icon('trash')}</button></div>`}</div>`;
}
function renderSettings() { return `<div class="settings-scrim" data-action="close-settings"></div><aside class="settings-panel"><div class="settings-header"><h2>Quick settings</h2><button class="icon-button" data-action="close-settings" aria-label="Close">${icon('close')}</button></div><p class="settings-caption">Make GPT-6 feel like yours.</p><section class="setting-group"><span class="setting-label">Theme</span><div class="theme-options"><button class="theme-option ${state.theme==='light'?'chosen':''}" data-set-theme="light"><span class="theme-preview light-preview"></span><strong>Light</strong></button><button class="theme-option ${state.theme==='dark'?'chosen':''}" data-set-theme="dark"><span class="theme-preview dark-preview"></span><strong>Dark</strong></button></div></section><section class="setting-group"><span class="setting-label">Inbox density</span><button class="density-option ${state.density==='comfortable'?'chosen':''}" data-density="comfortable"><span class="density-sample comfy"></span><span><strong>Comfortable</strong><small>More breathing room</small></span>${state.density==='comfortable'?icon('check'):''}</button><button class="density-option ${state.density==='compact'?'chosen':''}" data-density="compact"><span class="density-sample compact"></span><span><strong>Compact</strong><small>More messages on screen</small></span>${state.density==='compact'?icon('check'):''}</button></section><section class="settings-footer"><span class="setting-label">Inbox shortcuts</span><div><kbd>c</kbd> Compose <kbd>/</kbd> Search</div><div><kbd>e</kbd> Archive <kbd>#</kbd> Delete</div></section></aside>`; }
function renderLabelMenu() { return `<div class="popover label-popover"><strong>Label as</strong>${state.labels.map(label=>`<label><input type="checkbox" data-label-check="${esc(label)}" ${selected.size && [...selected].every(id=>state.threads.find(t=>t.id===id)?.labels.includes(label))?'checked':''}/> <span class="label-dot ${labelColor(label)}"></span>${esc(label)}</label>`).join('')}<div class="popover-actions"><button data-action="add-label">Create new</button><button class="primary-small" data-action="apply-labels">Apply</button></div></div>`; }
